const std = @import("std");
const CF = .{ .host_allo = [_][]const u8{ "localhost", "127.0.0.1", "[::1]" }, .secz_head = "X-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\nCross-Origin-Resource-Policy: same-origin\r\nContent-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'\r\n", .head_maxz = 32 * 1024, .page_defa = "ht-inde-main.html", .mime_octe = "application/octet-stream", .ui_exte = [_][]const u8{ ".html", ".css", ".js", ".ico" } };
pub const SECZ_HEAD = CF.secz_head;
pub const Requ = struct { meth: []const u8, path: []const u8, orig: ?[]const u8 = null, host: ?[]const u8 = null, secz_site: ?[]const u8 = null, secz_mode: ?[]const u8 = null, ifzz_none_matc: ?[]const u8 = null, acce_gzip: bool = false, chun: bool = false, cont_leng: usize = 0 };
pub const ParsErro = error{ Closed, BadRequest, UriTooLong, HeadersTooLarge };
pub fn statErro(erro: ParsErro) ?struct { code: u16, text: []const u8 } { return switch (erro) { error.Closed => null, error.BadRequest => .{ .code = 400, .text = "Bad Request" }, error.UriTooLong => .{ .code = 414, .text = "URI Too Long" }, error.HeadersTooLarge => .{ .code = 431, .text = "Request Header Fields Too Large" } }; }
pub fn pathOnly(path: []const u8) []const u8 { return if (std.mem.indexOfScalar(u8, path, '?')) |quer| path[0..quer] else path; }
pub fn pathQuer(path: []const u8) []const u8 { return if (std.mem.indexOfScalar(u8, path, '?')) |quer| path[quer + 1 ..] else ""; }
pub fn querValu(quer: []const u8, keyz: []const u8) ?[]const u8 { var iter = std.mem.splitScalar(u8, quer, '&'); while (iter.next()) |pair| { const eqzz = std.mem.indexOfScalar(u8, pair, '=') orelse continue; if (std.mem.eql(u8, pair[0..eqzz], keyz)) return pair[eqzz + 1 ..]; } return null; }
pub fn urlzDeco(outz: []u8, srcz: []const u8) []const u8 { var wpos: usize = 0; var rpos: usize = 0; while (rpos < srcz.len and wpos < outz.len) { if (srcz[rpos] == '%' and rpos + 2 < srcz.len) { const high = std.fmt.charToDigit(srcz[rpos + 1], 16) catch { outz[wpos] = srcz[rpos]; wpos += 1; rpos += 1; continue; }; const lowz = std.fmt.charToDigit(srcz[rpos + 2], 16) catch { outz[wpos] = srcz[rpos]; wpos += 1; rpos += 1; continue; }; outz[wpos] = high * 16 + lowz; wpos += 1; rpos += 3; } else if (srcz[rpos] == '+') { outz[wpos] = ' '; wpos += 1; rpos += 1; } else { outz[wpos] = srcz[rpos]; wpos += 1; rpos += 1; } } return outz[0..wpos]; }
pub fn hostOkay(host: ?[]const u8) bool { const name = host orelse return false; for (CF.host_allo) |allo| { if (std.ascii.eqlIgnoreCase(name, allo)) return true; if (name.len > allo.len and std.ascii.startsWithIgnoreCase(name, allo) and name[allo.len] == ':' and digiAllz(name[allo.len + 1 ..])) return true; } return false; }
pub const Gate = enum { okay, host, orig, fetc_site };
pub fn gate(requ: Requ, stat_getz: bool) Gate { if (!hostOkay(requ.host)) return .host; if (requ.orig) |orig| { if (!origHostMatc(orig, requ.host.?)) return .orig; } if (requ.secz_site) |site| { const same = std.mem.eql(u8, site, "same-origin") or std.mem.eql(u8, site, "none"); if (!same) { const navi = if (requ.secz_mode) |mode| std.mem.eql(u8, mode, "navigate") else false; if (!(navi and stat_getz)) return .fetc_site; } } return .okay; }
fn origHostMatc(orig: []const u8, host: []const u8) bool { const pref = "http://"; if (!std.ascii.startsWithIgnoreCase(orig, pref)) return false; return std.ascii.eqlIgnoreCase(orig[pref.len..], host); }
fn digiAllz(text: []const u8) bool { if (text.len == 0) return false; for (text) |char| if (!std.ascii.isDigit(char)) return false; return true; }
const MimeEntr = struct { exte: []const u8, mime: []const u8 }; const MIME_LIST = [_]MimeEntr{ .{ .exte = ".html", .mime = "text/html; charset=utf-8" }, .{ .exte = ".js", .mime = "application/javascript; charset=utf-8" }, .{ .exte = ".css", .mime = "text/css; charset=utf-8" }, .{ .exte = ".json", .mime = "application/json; charset=utf-8" }, .{ .exte = ".ico", .mime = "image/x-icon" }, .{ .exte = ".png", .mime = "image/png" }, .{ .exte = ".svg", .mime = "image/svg+xml" }, .{ .exte = ".woff2", .mime = "font/woff2" } };
pub fn mimeFind(path: []const u8) []const u8 { for (MIME_LIST) |item| { if (std.mem.endsWith(u8, path, item.exte)) return item.mime; } return CF.mime_octe; }
pub fn requRead(strm: *std.Io.net.Stream.Reader, line_bufz: []u8) ParsErro!Requ { const line = strm.interface.takeDelimiterExclusive('\n') catch |erro| return switch (erro) { error.StreamTooLong => error.UriTooLong, else => error.Closed }; strm.interface.discardAll(1) catch return error.Closed; const trim = std.mem.trimEnd(u8, line, "\r"); if (trim.len == 0) return error.BadRequest; if (trim.len > line_bufz.len / 2) return error.UriTooLong; @memcpy(line_bufz[0..trim.len], trim); const save = line_bufz[0..trim.len]; var part = std.mem.splitScalar(u8, save, ' '); const meth = part.next() orelse return error.BadRequest; const path = part.next() orelse return error.BadRequest; if (meth.len == 0 or path.len == 0) return error.BadRequest; var requ = Requ{ .meth = meth, .path = path }; var used: usize = trim.len; var totl: usize = 0; while (true) { const head = strm.interface.takeDelimiterExclusive('\n') catch |erro| return switch (erro) { error.StreamTooLong => error.HeadersTooLarge, else => error.Closed }; strm.interface.discardAll(1) catch return error.Closed; totl += head.len; if (totl > CF.head_maxz) return error.HeadersTooLarge; const htri = std.mem.trimEnd(u8, head, "\r"); if (htri.len == 0) break; const colo = std.mem.indexOfScalar(u8, htri, ':') orelse continue; const name = htri[0..colo]; const valu = std.mem.trim(u8, htri[colo + 1 ..], " \t"); if (std.ascii.eqlIgnoreCase(name, "Content-Length")) { requ.cont_leng = std.fmt.parseInt(usize, valu, 10) catch return error.BadRequest; continue; } if (std.ascii.eqlIgnoreCase(name, "Transfer-Encoding")) { requ.chun = true; continue; } if (std.ascii.eqlIgnoreCase(name, "Accept-Encoding")) { requ.acce_gzip = std.mem.indexOf(u8, valu, "gzip") != null; continue; } const slot: *?[]const u8 = if (std.ascii.eqlIgnoreCase(name, "Origin")) &requ.orig else if (std.ascii.eqlIgnoreCase(name, "Host")) &requ.host else if (std.ascii.eqlIgnoreCase(name, "Sec-Fetch-Site")) &requ.secz_site else if (std.ascii.eqlIgnoreCase(name, "Sec-Fetch-Mode")) &requ.secz_mode else if (std.ascii.eqlIgnoreCase(name, "If-None-Match")) &requ.ifzz_none_matc else continue; if (used + valu.len > line_bufz.len) return error.HeadersTooLarge; @memcpy(line_bufz[used..][0..valu.len], valu); slot.* = line_bufz[used..][0..valu.len]; used += valu.len; } return requ; }
pub fn bodyRead(allo: std.mem.Allocator, strm: *std.Io.net.Stream.Reader, leng: usize, maxz: usize) ?[]u8 { if (leng == 0 or leng > maxz) return null; const bufz = allo.alloc(u8, leng) catch return null; strm.interface.readSliceAll(bufz) catch { allo.free(bufz); return null; }; return bufz; }
pub fn respSend(strm: *std.Io.net.Stream.Writer, code: u16, stat: []const u8, body: []const u8) !void { try strm.interface.print("HTTP/1.1 {d} {s}\r\nContent-Type: application/json; charset=utf-8\r\nCache-Control: no-store\r\n" ++ SECZ_HEAD ++ "Content-Length: {d}\r\nConnection: close\r\n\r\n{s}", .{ code, stat, body.len, body }); try strm.interface.flush(); }
pub fn respRawzSend(strm: *std.Io.net.Stream.Writer, code: u16, stat: []const u8, mime: []const u8, body: []const u8) !void { try strm.interface.print("HTTP/1.1 {d} {s}\r\nContent-Type: {s}\r\nCache-Control: no-store\r\n" ++ SECZ_HEAD ++ "Content-Length: {d}\r\nConnection: close\r\n\r\n", .{ code, stat, mime, body.len }); try strm.interface.writeAll(body); try strm.interface.flush(); }
pub fn respEtagSend(strm: *std.Io.net.Stream.Writer, ifnm: ?[]const u8, etag: []const u8, body: []const u8) !void { if (ifnm) |valu| if (std.mem.eql(u8, valu, etag)) { try strm.interface.print("HTTP/1.1 304 Not Modified\r\nETag: {s}\r\nCache-Control: no-cache\r\n" ++ SECZ_HEAD ++ "Content-Length: 0\r\nConnection: close\r\n\r\n", .{etag}); try strm.interface.flush(); return; }; try strm.interface.print("HTTP/1.1 200 OK\r\nContent-Type: application/json; charset=utf-8\r\nETag: {s}\r\nCache-Control: no-cache\r\n" ++ SECZ_HEAD ++ "Content-Length: {d}\r\nConnection: close\r\n\r\n", .{ etag, body.len }); try strm.interface.writeAll(body); try strm.interface.flush(); }
pub const StatOutz = struct { body: []const u8, mime: []const u8, etag: []const u8, enco: ?[]const u8 = null };
pub fn respStatSend(strm: *std.Io.net.Stream.Writer, ifnm: ?[]const u8, outz: StatOutz) !void { if (ifnm) |valu| if (std.mem.eql(u8, valu, outz.etag)) { try strm.interface.print("HTTP/1.1 304 Not Modified\r\nETag: {s}\r\nCache-Control: no-cache\r\nVary: Accept-Encoding\r\n" ++ SECZ_HEAD ++ "Content-Length: 0\r\nConnection: close\r\n\r\n", .{outz.etag}); try strm.interface.flush(); return; }; try strm.interface.print("HTTP/1.1 200 OK\r\nContent-Type: {s}\r\nETag: {s}\r\nCache-Control: no-cache\r\nVary: Accept-Encoding\r\n" ++ SECZ_HEAD, .{ outz.mime, outz.etag }); if (outz.enco) |enco| try strm.interface.print("Content-Encoding: {s}\r\n", .{enco}); try strm.interface.print("Content-Length: {d}\r\nConnection: close\r\n\r\n", .{outz.body.len}); try strm.interface.writeAll(outz.body); try strm.interface.flush(); }
pub fn etagHash(bufz: []u8, data: []const u8) []const u8 { const hash = std.hash.Wyhash.hash(0, data); return std.fmt.bufPrint(bufz, "\"{x:0>16}\"", .{hash}) catch "\"0\""; }
pub fn statPathSafe(allo: std.mem.Allocator, root: []const u8, path: []const u8) ?[]const u8 { const relz = statRelz(path) orelse return null; const join = std.fs.path.resolve(allo, &.{ root, relz }) catch return null; const root_abso = std.fs.path.resolve(allo, &.{root}) catch return null; if (!std.mem.startsWith(u8, join, root_abso)) return null; return join; }
pub fn statRelz(path: []const u8) ?[]const u8 { const clea = pathOnly(path); const relz = if (std.mem.eql(u8, clea, "/") or clea.len == 0) CF.page_defa else clea[1..]; if (relz.len == 0) return null; if (std.mem.indexOf(u8, relz, "..") != null) return null; if (std.mem.indexOfScalar(u8, relz, '%') != null) return null; if (std.mem.indexOfScalar(u8, relz, ':') != null) return null; if (std.mem.indexOfScalar(u8, relz, '\\') != null) return null; if (std.mem.indexOfScalar(u8, relz, '/') != null) return null; if (!uizzTypeOkay(relz)) return null; return relz; }
pub fn uizzTypeOkay(name: []const u8) bool { const exte = std.fs.path.extension(name); for (CF.ui_exte) |okay| if (std.ascii.eqlIgnoreCase(exte, okay)) return true; return false; }
